35	export type DiscourseNodeShape = TLBaseShape<
36	  "discourse-node",
37	  {
38	    w: number;
39	    h: number;
40	    // asset-style source: asset:obsidian.blockref.<id>
41	    src: string | null;
42	    // Cached display data
43	    title: string;
44	    nodeTypeId: string;
45	    imageSrc?: string;
46	    size: TLDefaultSizeStyle;
47	    fontFamily: TLDefaultFontStyle;
48	  }
49	>;
50	
51	export type DiscourseNodeUtilOptions = {
52	  app: App;
53	  plugin: DiscourseGraphPlugin;
54	  canvasFile: TFile;
55	};
56	
57	/** Default props for new discourse node shapes. Used by getDefaultProps and buildDiscourseNodeShapeRecord. */
58	export const DEFAULT_DISCOURSE_NODE_PROPS: DiscourseNodeShape["props"] = {
59	  w: 200,
60	  h: 100,
61	  src: null,
62	  title: "",
63	  nodeTypeId: "",
64	  imageSrc: undefined,
65	  size: "s",
66	  fontFamily: "sans",
67	};
68	
69	export type BuildDiscourseNodeShapeRecordParams = {
70	  id: TLShapeId;
71	  x: number;
72	  y: number;
73	  props: Partial<DiscourseNodeShape["props"]> &
74	    Pick<DiscourseNodeShape["props"], "src" | "title" | "nodeTypeId">;
75	};
76	
77	/**
78	 * Build a full DiscourseNodeShape record for editor.createShape.
79	 * Merges given props with DEFAULT_DISCOURSE_NODE_PROPS.
80	 */
81	export const buildDiscourseNodeShapeRecord = (
82	  editor: Editor,
83	  { id, x, y, props: propsPartial }: BuildDiscourseNodeShapeRecordParams,
84	): DiscourseNodeShape => {
85	  const props: DiscourseNodeShape["props"] = {
86	    ...DEFAULT_DISCOURSE_NODE_PROPS,
87	    ...propsPartial,
88	  };
89	  return {
90	    id,
91	    typeName: "shape",
92	    type: "discourse-node",
93	    x,
94	    y,
95	    rotation: 0,
96	    index: editor.getHighestIndexForParent(editor.getCurrentPageId()),
97	    parentId: editor.getCurrentPageId(),
98	    isLocked: false,
99	    opacity: 1,
100	    meta: {},
101	    props,
102	  };
103	};
104	
105	export class DiscourseNodeUtil extends BaseBoxShapeUtil<DiscourseNodeShape> {
106	  static type = "discourse-node" as const;
107	  declare options: DiscourseNodeUtilOptions;
108	
109	  static props = {
110	    w: T.number,
111	    h: T.number,
112	    src: T.string.nullable(),
113	    title: T.string.optional(),
114	    nodeTypeId: T.string.nullable().optional(),
115	    imageSrc: T.string.optional(),
116	    size: DefaultSizeStyle,
117	    fontFamily: DefaultFontStyle,
118	  };
119	
120	  getDefaultProps(): DiscourseNodeShape["props"] {
121	    return { ...DEFAULT_DISCOURSE_NODE_PROPS };
122	  }
123	
124	  override isAspectRatioLocked = () => false;
125	  override canResize = () => true;
126	
127	  override onResize(
128	    shape: DiscourseNodeShape,
129	    info: TLResizeInfo<DiscourseNodeShape>,
130	  ) {
131	    return resizeBox(shape, info);
132	  }
133	
134	  override onDoubleClick = (shape: DiscourseNodeShape) => {
135	    void (async () => {
136	      const file = await this.getFile(shape, {
137	        app: this.options.app,
138	        canvasFile: this.options.canvasFile,
139	      });
140	
141	      if (!file) {
142	        return;
143	      }
144	
145	      const fileCache = this.options.app.metadataCache.getFileCache(file);
146	      const nodeTypeId = fileCache?.frontmatter?.nodeTypeId as
147	        | string
148	        | undefined;
149	
150	      const nodeType = nodeTypeId
151	        ? this.options.plugin.settings.nodeTypes.find(
152	            (nt) => nt.id === nodeTypeId,
153	          )
154	        : undefined;
155	
156	      const modal = new ModifyNodeModal(this.options.app, {
157	        nodeTypes: this.options.plugin.settings.nodeTypes,
158	        plugin: this.options.plugin,
159	        onSubmit: async ({ title: newTitle, initialFile: file }) => {
160	          const editor = this.editor;
161	          if (!editor || !file) return;
162	
163	          const formattedName = newTitle.trim();
164	          if (formattedName) {
165	            // Rename the file
166	            const folderPath =
167	              nodeType?.folderPath?.trim() ||
168	              this.options.plugin.settings.nodesFolderPath.trim();
169	            let newPath = "";
170	            if (folderPath) {
171	              const folderExists =
172	                this.options.app.vault.getAbstractFileByPath(folderPath);
173	              if (!folderExists) {
174	                await this.options.app.vault.createFolder(folderPath);
175	              }
176	              newPath = `${folderPath}/${formattedName}.md`;
177	            } else {
178	              const dirPath = file.parent?.path ?? "";
179	              newPath = dirPath
180	                ? `${dirPath}/${formattedName}.md`
181	                : `${formattedName}.md`;
182	            }
183	
184	            await this.options.app.fileManager.renameFile(file, newPath);
185	
186	            editor.updateShape<DiscourseNodeShape>({
187	              id: shape.id,
188	              type: "discourse-node",
189	              props: {
190	                ...shape.props,
191	                title: formattedName,
192	              },
193	            });
194	          }
195	        },
196	        initialFile: file,
197	        initialNodeType: nodeType,
198	      });
199	
200	      modal.open();
201	    })();
202	  };
203	
204	  component(shape: DiscourseNodeShape) {
205	    return (
206	      <HTMLContainer>
207	        {createElement(discourseNodeContent, {
208	          shape,
209	          app: this.options.app,
210	          canvasFile: this.options.canvasFile,
211	          plugin: this.options.plugin,
212	        })}
213	      </HTMLContainer>
214	    );
215	  }
216	
217	  indicator(shape: DiscourseNodeShape) {
218	    const { bounds } = this.editor.getShapeGeometry(shape);
219	    return (
220	      <rect
221	        width={toDomPrecision(bounds.width)}
222	        height={toDomPrecision(bounds.height)}
223	      />
224	    );
225	  }
226	
227	  getFile = async (
228	    shape: DiscourseNodeShape,
229	    ctx: { app: App; canvasFile: TFile },
230	  ): Promise<TFile | null> => {
231	    const app = ctx?.app ?? this.options.app;
232	    const canvasFile = ctx?.canvasFile ?? this.options.canvasFile;
233	    return resolveLinkedFileFromSrc({
234	      app,
235	      canvasFile,
236	      src: shape.props.src ?? undefined,
