239	
240	  getFrontmatter = async (
241	    shape: DiscourseNodeShape,
242	    ctx: { app: App; canvasFile: TFile },
243	  ): Promise<FrontmatterRecord | null> => {
244	    const app = ctx?.app ?? this.options.app;
245	    const file = await this.getFile(shape, ctx);
246	    if (!file) return null;
247	    return getFrontmatterForFile(app, file);
248	  };
249	
250	  getRelations = async (
251	    shape: DiscourseNodeShape,
252	    ctx: { app: App; canvasFile: TFile },
253	  ): Promise<unknown[]> => {
254	    const frontmatter = await this.getFrontmatter(shape, ctx);
255	    if (!frontmatter) return [];
256	    // TODO: derive relations from frontmatter
257	    return [];
258	  };
259	}
