261	const discourseNodeContent = memo(
262	  ({
263	    shape,
264	    app,
265	    canvasFile,
266	    plugin,
267	  }: {
268	    shape: DiscourseNodeShape;
269	    app: App;
270	    canvasFile: TFile;
271	    plugin: DiscourseGraphPlugin;
272	  }) => {
273	    const editor = useEditor();
274	    const { src, title, nodeTypeId } = shape.props;
275	    const nodeType = getNodeTypeById(plugin, nodeTypeId);
276	
277	    const isHovered = useValue(
278	      "is hovered",
279	      () => {
280	        return editor.getHoveredShapeId() === shape.id;
281	      },
282	      [editor, shape.id],
283	    );
284	
285	    useEffect(() => {
286	      const loadNodeData = async () => {
287	        if (!src) {
288	          editor.updateShape<DiscourseNodeShape>({
289	            id: shape.id,
290	            type: "discourse-node",
291	            props: {
292	              ...shape.props,
293	              title: "(no source)",
294	            },
295	          });
296	          return;
297	        }
298	
299	        try {
300	          const linkedFile = await resolveLinkedFileFromSrc({
301	            app,
302	            canvasFile,
303	            src,
304	          });
305	
306	          if (!linkedFile) {
307	            return;
308	          }
309	
310	          if (linkedFile.basename !== shape.props.title) {
311	            editor.updateShape<DiscourseNodeShape>({
312	              id: shape.id,
313	              type: "discourse-node",
314	              props: {
315	                ...shape.props,
316	                title: linkedFile.basename,
317	              },
318	            });
319	          }
320	
321	          let currentImageSrc = shape.props.imageSrc;
322	          if (nodeType?.keyImage) {
323	            const imageSrc = await getFirstImageSrcForFile(app, linkedFile);
324	
325	            if (imageSrc && imageSrc !== shape.props.imageSrc) {
326	              currentImageSrc = imageSrc;
327	              editor.updateShape<DiscourseNodeShape>({
328	                id: shape.id,
329	                type: "discourse-node",
330	                props: {
331	                  ...shape.props,
332	                  imageSrc,
333	                },
334	              });
335	            }
336	          } else if (shape.props.imageSrc) {
337	            currentImageSrc = undefined;
338	            editor.updateShape<DiscourseNodeShape>({
339	              id: shape.id,
340	              type: "discourse-node",
341	              props: {
342	                ...shape.props,
343	                imageSrc: undefined,
344	              },
345	            });
346	          }
347	
348	          // Recalculate size when title, image, font size, or font family changes
349	          const { w, h } = await calcDiscourseNodeSize({
350	            title: linkedFile.basename,
351	            nodeTypeId: shape.props.nodeTypeId,
352	            imageSrc: currentImageSrc,
353	            plugin,
354	            size: shape.props.size ?? "s",
355	            fontFamily: shape.props.fontFamily ?? "draw",
356	          });
357	          // Only update dimensions if they differ significantly (>1px)
358	          if (
359	            Math.abs((shape.props.w || 0) - w) > 1 ||
360	            Math.abs((shape.props.h || 0) - h) > 1
361	          ) {
362	            editor.updateShape<DiscourseNodeShape>({
363	              id: shape.id,
364	              type: "discourse-node",
365	              props: {
366	                ...shape.props,
367	                w,
368	                h,
369	              },
370	            });
371	          }
372	        } catch (error) {
373	          console.error("Error loading node data", error);
374	          return;
375	        }
376	      };
377	
378	      void loadNodeData();
379	
380	      return () => {
381	        return;
382	      };
383	      // Trigger when content changes
384	      // eslint-disable-next-line react-hooks/exhaustive-deps
385	    }, [
386	      src,
387	      shape.id,
388	      shape.props.title,
389	      shape.props.nodeTypeId,
390	      shape.props.imageSrc,
391	      editor,
392	      app,
393	      canvasFile,
394	      plugin,
395	      nodeType?.keyImage,
396	    ]);
397	
398	    const handleOpenInSidebar = async (): Promise<void> => {
399	      if (!src) {
400	        showToast({
401	          severity: "warning",
402	          title: "Cannot open node",
403	          description: "No source file linked",
404	        });
405	        return;
406	      }
407	      try {
408	        const linkedFile = await resolveLinkedFileFromSrc({
409	          app,
410	          canvasFile,
411	          src,
412	        });
413	
414	        if (!linkedFile) {
415	          showToast({
416	            severity: "warning",
417	            title: "Cannot open node",
418	            description: "Linked file not found",
419	          });
420	          return;
421	        }
422	
423	        await openFileInSidebar(app, linkedFile);
424	        editor.selectNone();
425	      } catch (error) {
426	        console.error("Error opening linked file:", error);
427	        showToast({
428	          severity: "error",
429	          title: "Error",
430	          description: "Failed to open linked file",
431	        });
432	      }
433	    };
434	    const fontSize = FONT_SIZES[shape.props.size];
435	    const fontFamily = FONT_FAMILIES[shape.props.fontFamily];
436	
437	    return (
438	      <div
439	        style={{
440	          backgroundColor: nodeType?.color ?? "",
441	        }}
442	        // NOTE: These Tailwind classes (p-2, border-2, rounded-md, m-1, text-base, m-0, text-sm)
443	        // correspond to constants in nodeConstants.ts. If you change these classes, update the
444	        // constants and the measureNodeText function to keep measurements accurate.
445	        className="relative box-border flex h-full w-full flex-col items-start justify-center overflow-hidden rounded-md border-2 p-2"
446	      >
447	        {isHovered && (
448	          <button
449	            onClick={(e) => {
450	              e.stopPropagation();
451	              void handleOpenInSidebar();
452	            }}
453	            onPointerDown={(e) => {
454	              e.stopPropagation();
455	              e.preventDefault();
456	            }}
457	            onPointerUp={(e) => {
458	              e.stopPropagation();
459	            }}
460	            className="absolute left-1 top-1 z-10 flex h-6 w-6 cursor-pointer items-center justify-center rounded border border-black/10 bg-white/90 p-1 shadow-sm transition-all duration-200 hover:bg-white"
461	            style={{
462	              pointerEvents: "auto",
463	            }}
464	            title="Open in sidebar"
465	          >
466	            <svg
467	              xmlns="http://www.w3.org/2000/svg"
468	              width="16"
469	              height="16"
470	              viewBox="0 0 24 24"
471	              fill="none"
472	              stroke="currentColor"
473	              strokeWidth="2"
474	              strokeLinecap="round"
475	              strokeLinejoin="round"
476	            >
477	              <rect x="3" y="3" width="18" height="18" rx="2" ry="2" />
478	              <line x1="15" y1="3" x2="15" y2="21" />
479	            </svg>
480	          </button>
481	        )}
482	
483	        {shape.props.imageSrc ? (
484	          <div className="mt-2 flex min-h-0 w-full flex-1 items-center justify-center overflow-hidden">
485	            <img
486	              src={shape.props.imageSrc}
487	              loading="lazy"
488	              decoding="async"
489	              draggable="false"
490	              className="max-h-full max-w-full object-contain"
491	            />
492	          </div>
493	        ) : null}
494	        <h1
495	          className="m-1"
496	          style={{
497	            fontSize: `${fontSize}px`,
498	            fontFamily,
499	          }}
500	        >
501	          {title || "..."}
502	        </h1>
503	      </div>
504	    );
505	  },
506	);
507	
508	discourseNodeContent.displayName = "DiscourseNodeContent";
509	
