95	  // of our writes, and replaced after each external change we merge in.
96	  const lastKnownFileRef = useRef<CanvasFileState | null>(initialFileState);
97	  const unreadableSaveRetriesRef = useRef(0);
98	  const editorRef = useRef<Editor>(null);
99	  const plugin = usePlugin();
100	
101	  useCanvasFileSync({
102	    file,
103	    store: currentStore,
104	    lastKnownFileRef,
105	    isSavingRef,
106	  });
107	
108	  const customShapeUtils = [
109	    ...defaultShapeUtils,
110	    createDiscourseNodeUtil({
111	      app: plugin.app,
112	      canvasFile: file,
113	      plugin,
114	    }),
115	    createDiscourseRelationUtil({
