142	        e.key === "Enter" &&
143	        e.metaKey &&
144	        e.altKey &&
145	        !e.shiftKey &&
146	        !e.ctrlKey
147	      ) {
148	        const hoveredShapeId = editor.getHoveredShapeId();
149	        if (!hoveredShapeId) return;
