177	  const saveChanges = useCallback(async (): Promise<SaveResult> => {
178	    // Prevent concurrent saves
179	    if (isSavingRef.current || !canvasUuid) {
180	      return "skipped";
181	    }
182	
183	    isSavingRef.current = true;
184	    try {
185	      const newData = getTLDataTemplate({
186	        pluginVersion: plugin.manifest.version,
187	        tldrawFile: createRawTldrawFile(currentStore),
188	        uuid: canvasUuid,
189	      });
190	      const stringifiedData = JSON.stringify(newData, null, "\t");
191	
192	      if (stringifiedData === lastKnownFileRef.current?.text) {
193	        return "skipped";
194	      }
195	
196	      const previousState = lastKnownFileRef.current;
197	      const write: { outcome: WriteOutcome; onDisk: CanvasFileState | null } = {
198	        outcome: "unchanged",
199	        onDisk: null,
200	      };
201	
202	      try {
203	        // Vault.process serialises read-modify-write, so Markdown edits outside
204	        // the canvas block made by another writer in the meantime are kept.
205	        const written = await plugin.app.vault.process(file, (content) => {
206	          if (!hasCanvasBlock(content)) return content;
207	
208	          write.onDisk = parseCanvasFileState(content);
209	          if (!write.onDisk) {
210	            write.outcome = "unreadable";
211	            return content;
212	          }
213	          // Never overwrite a version of the file this tab has not merged.
214	          if (write.onDisk.text !== lastKnownFileRef.current?.text) {
215	            write.outcome = "diverged";
216	            return content;
217	          }
218	
219	          const updated = getUpdatedMdContent(content, stringifiedData);
220	          if (updated === content) return content;
221	
222	          // Recorded before the write so the vault `modify` event it triggers
223	          // is recognised as our own and not merged back in.
224	          lastKnownFileRef.current = { text: stringifiedData, data: newData };
225	          write.outcome = "written";
226	          return updated;
227	        });
228	
229	        if (write.outcome === "diverged" && write.onDisk) {
230	          // Merge the newer file in and retry so the next write carries both.
231	          const applied = applyCanvasFileState({
232	            store: currentStore,
233	            base: lastKnownFileRef.current,
234	            incoming: write.onDisk,
235	          });
236	          if (applied) lastKnownFileRef.current = write.onDisk;
237	          unreadableSaveRetriesRef.current = 0;
238	          return "retry";
239	        }
240	
241	        if (write.outcome === "unreadable") {
242	          unreadableSaveRetriesRef.current += 1;
243	          if (unreadableSaveRetriesRef.current <= MAX_UNREADABLE_SAVE_RETRIES) {
244	            return "retry";
245	          }
246	          unreadableSaveRetriesRef.current = 0;
247	          new Notice(
248	            "Canvas file contains invalid data; your latest changes were not saved.",
249	          );
250	          return "skipped";
251	        }
252	
253	        unreadableSaveRetriesRef.current = 0;
254	        if (write.outcome === "unchanged") return "skipped";
255	
256	        const savedState = parseCanvasFileState(written);
257	        if (!savedState) {
258	          throw new Error(
259	            "Failed to verify saved TLDraw data: Could not find data block",
260	          );
261	        }
262	        if (JSON.stringify(savedState.data) !== JSON.stringify(newData)) {
263	          console.warn(
264	            "Saved data differs from expected (this is normal during concurrent operations)",
265	          );
266	        }
267	        return "saved";
268	      } catch (error) {
269	        if (write.outcome === "written")
270	          lastKnownFileRef.current = previousState;
271	        console.error("Error saving/verifying TLDraw data:", error);
272	        // Reload the editor state from file since save failed
273	        const fileState = parseCanvasFileState(
274	          await plugin.app.vault.read(file),
275	        );
276	        if (fileState) {
277	          const { store: newStore } = processInitialData(
278	            fileState.data,
279	            assetStore,
280	            {
281	              app: plugin.app,
282	              canvasFile: file,
283	              plugin,
284	            },
285	          );
286	          lastKnownFileRef.current = fileState;
287	          setCurrentStore(newStore);
288	        }
289	        return "skipped";
290	      }
291	    } finally {
292	      isSavingRef.current = false;
293	    }
294	  }, [file, plugin, currentStore, assetStore, canvasUuid]);
295	
296	  useEffect(() => {
297	    const scheduleSave = (): void => {
298	      if (saveTimeoutRef.current) {
299	        clearTimeout(saveTimeoutRef.current);
300	      }
301	      saveTimeoutRef.current = setTimeout(() => {
302	        // If a save is already in progress, try again after it completes
303	        if (isSavingRef.current) {
304	          scheduleSave();
305	          return;
306	        }
307	        void saveChanges().then((result) => {
308	          if (result === "retry") scheduleSave();
309	        });
310	      }, DEFAULT_SAVE_DELAY);
311	    };
312	
313	    const unsubscribe = currentStore.listen(scheduleSave, {
314	      source: "user",
315	      scope: "document",
316	    });
317	
318	    return () => {
319	      unsubscribe();
320	      if (saveTimeoutRef.current) {
321	        clearTimeout(saveTimeoutRef.current);
322	      }
323	    };
324	  }, [currentStore, saveChanges]);
