348	        } as unknown as TLDefaultExternalContentHandlerOpts,
349	      });
350	    });
351	
352	    editor.on("event", (event) => {
353	      // Handle pointer events
354	      if (event.type !== "pointer") return;
355	      const e = event as TLPointerEventInfo;
356	
357	      if (e.type === "pointer" && e.name === "right_click") {
358	        const container = editor.getContainer();
