1	import { TextFileView, TFile, WorkspaceLeaf } from "obsidian";
2	import { VIEW_TYPE_TLDRAW_DG_PREVIEW } from "~/constants";
3	import { Root, createRoot } from "react-dom/client";
4	import { TldrawPreviewComponent } from "./TldrawViewComponent";
5	import { TLStore } from "tldraw";
6	import React from "react";
7	import DiscourseGraphPlugin from "~/index";
8	import { processInitialData } from "~/components/canvas/utils/tldraw";
9	import { ObsidianTLAssetStore } from "~/components/canvas/stores/assetStore";
10	import { PluginProvider } from "../PluginContext";
11	import {
12	  CanvasFileState,
13	  parseCanvasFileState,
14	} from "~/components/canvas/utils/canvasFileSync";
15	
16	export class TldrawView extends TextFileView {
17	  plugin: DiscourseGraphPlugin;
18	  private reactRoot?: Root;
19	  private store: TLStore | null = null;
20	  private assetStore: ObsidianTLAssetStore | null = null;
21	  private canvasUuid: string | null = null;
22	  private initialFileState: CanvasFileState | null = null;
23	  private onUnloadCallbacks: (() => void)[] = [];
24	
25	  constructor(leaf: WorkspaceLeaf, plugin: DiscourseGraphPlugin) {
26	    super(leaf);
27	    this.plugin = plugin;
28	    this.navigation = true;
29	  }
30	
31	  getViewType(): string {
32	    return VIEW_TYPE_TLDRAW_DG_PREVIEW;
33	  }
34	
35	  getDisplayText(): string {
36	    return this.file?.basename ?? "Discourse Graph Canvas Preview";
37	  }
38	
39	  getViewData(): string {
40	    return this.data;
41	  }
42	
43	  setViewData(data: string): void {
44	    this.data = data;
45	  }
46	
47	  clear(): void {
48	    this.data = "";
49	  }
50	
51	  protected get tldrawContainer() {
52	    return this.containerEl.children[1];
53	  }
54	
55	  override onload(): void {
56	    super.onload();
57	    this.contentEl.addClass("tldraw-view-content");
58	    this.addAction("file-text", "View as markdown", () =>
59	      this.leaf.setViewState({
60	        type: "markdown",
61	        state: this.leaf.view.getState(),
62	      }),
63	    );
64	  }
65	
66	  // eslint-disable-next-line @typescript-eslint/require-await
67	  async onOpen(): Promise<void> {
68	    const container = this.tldrawContainer;
69	    if (!container) return;
70	
71	    container.empty();
72	  }
73	
74	  async onLoadFile(file: TFile): Promise<void> {
75	    await super.onLoadFile(file);
76	
77	    const fileData = await this.app.vault.read(file);
78	
79	    const assetStore = new ObsidianTLAssetStore(
80	      `tldraw-${encodeURIComponent(file.path)}`,
81	      {
82	        app: this.app,
83	        file,
84	        plugin: this.plugin,
85	      },
86	    );
87	    const store = this.createStore(fileData, assetStore);
88	
89	    if (!store) {
90	      return;
91	    }
92	
93	    this.assetStore = assetStore;
94	    await this.setStore(store);
95	  }
96	
97	  private createStore(
98	    fileData: string,
99	    assetStore: ObsidianTLAssetStore,
100	  ): TLStore | undefined {
101	    try {
102	      const fileState = parseCanvasFileState(fileData);
103	      if (!fileState) {
104	        return;
105	      }
106	
107	      this.initialFileState = fileState;
108	      const { data } = fileState;
109	      if (data.meta?.uuid) {
110	        this.canvasUuid = data.meta.uuid;
111	      } else {
112	        this.canvasUuid = window.crypto.randomUUID();
113	      }
114	
115	      if (!this.file) {
116	        return;
117	      }
118	
119	      const { store } = processInitialData(data, assetStore, {
120	        app: this.app,
121	        canvasFile: this.file,
122	        plugin: this.plugin,
123	      });
124	
125	      return store;
126	    } catch (e) {
127	      console.error("Failed to create store from file data", e);
128	      return;
129	    }
130	  }
131	
132	  private assertInitialized(): void {
133	    if (!this.file) throw new Error("TldrawView not initialized: missing file");
134	    if (!this.assetStore)
135	      throw new Error("TldrawView not initialized: missing assetStore");
136	    if (!this.store)
137	      throw new Error("TldrawView not initialized: missing store");
138	  }
139	
140	  private createReactRoot(entryPoint: Element, store: TLStore) {
141	    const root = createRoot(entryPoint);
142	    if (!this.file) throw new Error("TldrawView not initialized: missing file");
143	    if (!this.assetStore)
144	      throw new Error("TldrawView not initialized: missing assetStore");
145	    if (!this.store)
146	      throw new Error("TldrawView not initialized: missing store");
147	    if (!this.canvasUuid)
148	      throw new Error("TldrawView not initialized: missing canvas UUID");
149	
150	    if (!this.assetStore) {
151	      return;
152	    }
153	
154	    root.render(
155	      <React.StrictMode>
156	        <PluginProvider plugin={this.plugin}>
157	          <TldrawPreviewComponent
158	            store={store}
159	            file={this.file}
160	            assetStore={this.assetStore}
161	            canvasUuid={this.canvasUuid}
162	            initialFileState={this.initialFileState}
163	          />
164	        </PluginProvider>
165	      </React.StrictMode>,
166	    );
167	    return root;
168	  }
169	
170	  protected async setStore(store: TLStore) {
171	    if (this.store) {
172	      try {
173	        this.store.dispose();
174	      } catch (e) {
175	        console.error("Failed to dispose old store", e);
176	      }
177	    }
178	
179	    this.store = store;
180	    if (this.tldrawContainer) {
181	      await this.refreshView();
182	    }
183	  }
184	
185	  private async refreshView() {
186	    if (!this.store) return;
187	
188	    if (this.reactRoot) {
189	      try {
190	        const container = this.tldrawContainer;
191	        if (container?.hasChildNodes()) {
192	          this.reactRoot.unmount();
193	        }
194	      } catch (e) {
195	        console.error("Failed to unmount React root", e);
196	      }
197	      this.reactRoot = undefined;
198	    }
199	
200	    const container = this.tldrawContainer;
201	    if (container) {
202	      this.reactRoot = this.createReactRoot(container, this.store);
203	      await new Promise((resolve) => setTimeout(resolve, 0)); // Wait for React to render
204	    }
205	  }
206	
207	  registerOnUnloadFile(callback: () => void) {
208	    this.onUnloadCallbacks.push(callback);
209	  }
210	
211	  async onUnloadFile(file: TFile): Promise<void> {
212	    const callbacks = [...this.onUnloadCallbacks];
213	    this.onUnloadCallbacks = [];
214	    callbacks.forEach((cb) => cb());
215	
216	    if (this.assetStore) {
217	      this.assetStore.dispose();
218	      this.assetStore = null;
219	    }
220	
221	    return super.onUnloadFile(file);
222	  }
223	
224	  async onClose() {
225	    await super.onClose();
226	
227	    if (this.reactRoot) {
228	      try {
229	        const container = this.tldrawContainer;
230	        if (container?.hasChildNodes()) {
231	          this.reactRoot.unmount();
232	        }
233	      } catch (e) {
234	        console.error("Failed to unmount React root", e);
235	      }
236	      this.reactRoot = undefined;
237	    }
238	
239	    if (this.store) {
240	      try {
241	        this.store.dispose();
242	      } catch (e) {
243	        console.error("Failed to dispose store", e);
244	      }
245	      this.store = null;
246	    }
247	
248	    if (this.assetStore) {
249	      this.assetStore.dispose();
250	      this.assetStore = null;
251	    }
252	  }
253	}
